CREATE TABLE users(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL,is_admin boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,created timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires timestamptz NOT NULL,created timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_limits(key text PRIMARY KEY,attempts integer NOT NULL,window_start timestamptz NOT NULL);
CREATE TABLE tenants(id text PRIMARY KEY,name text NOT NULL,currency text NOT NULL DEFAULT 'PKR',address text NOT NULL DEFAULT '',tax_number text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),invoice_seq bigint NOT NULL DEFAULT 0,created timestamptz NOT NULL DEFAULT now());
CREATE TABLE members(id text PRIMARY KEY,tenant text NOT NULL REFERENCES tenants(id),user_id text NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('Owner','Manager','Cashier','Stock Manager')),active boolean NOT NULL DEFAULT true,UNIQUE(tenant,user_id));
CREATE TABLE products(id text PRIMARY KEY,tenant text NOT NULL REFERENCES tenants(id),sku text NOT NULL,barcode text,name text NOT NULL,category text NOT NULL,price bigint NOT NULL CHECK(price>=0),cost bigint NOT NULL DEFAULT 0 CHECK(cost>=0),stock bigint NOT NULL DEFAULT 0 CHECK(stock>=0),reorder bigint NOT NULL DEFAULT 5 CHECK(reorder>=0),active boolean NOT NULL DEFAULT true,created timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant,sku),UNIQUE(tenant,barcode),UNIQUE(tenant,id));
CREATE TABLE sales(id text PRIMARY KEY,tenant text NOT NULL REFERENCES tenants(id),request text NOT NULL,signature text NOT NULL,invoice_number text NOT NULL,customer text NOT NULL,subtotal bigint NOT NULL,discount bigint NOT NULL DEFAULT 0,tax_bps integer NOT NULL DEFAULT 0,tax bigint NOT NULL DEFAULT 0,total bigint NOT NULL,tendered bigint NOT NULL DEFAULT 0,payment text NOT NULL CHECK(payment IN ('cash','external')),status text NOT NULL DEFAULT 'completed' CHECK(status IN ('completed','returned')),seller_name text NOT NULL,seller_address text NOT NULL,seller_tax_number text NOT NULL,currency text NOT NULL,actor text NOT NULL,created timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant,request),UNIQUE(tenant,invoice_number),UNIQUE(tenant,id));
CREATE TABLE sale_items(id text PRIMARY KEY,sale text NOT NULL,tenant text NOT NULL,product text NOT NULL,name text NOT NULL,sku text NOT NULL,quantity bigint NOT NULL CHECK(quantity>0),price bigint NOT NULL,cost bigint NOT NULL,FOREIGN KEY(tenant,sale) REFERENCES sales(tenant,id),FOREIGN KEY(tenant,product) REFERENCES products(tenant,id));
CREATE TABLE movements(id text PRIMARY KEY,tenant text NOT NULL,product text NOT NULL,quantity bigint NOT NULL,type text NOT NULL CHECK(type IN ('OPENING','IN','OUT','SALE','RETURN')),notes text NOT NULL DEFAULT '',actor text NOT NULL,created timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant,product) REFERENCES products(tenant,id));
CREATE INDEX movements_tenant_date ON movements(tenant,created DESC);
CREATE INDEX sales_tenant_date ON sales(tenant,created DESC);
CREATE TABLE audit(id text PRIMARY KEY,tenant text REFERENCES tenants(id),actor text NOT NULL,action text NOT NULL,details text NOT NULL,created timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_tenant_date ON audit(tenant,created DESC);
CREATE FUNCTION apply_stock_movement() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE products SET stock=stock+NEW.quantity WHERE id=NEW.product AND tenant=NEW.tenant;RETURN NEW;END $$;
CREATE TRIGGER movement_updates_stock AFTER INSERT ON movements FOR EACH ROW EXECUTE FUNCTION apply_stock_movement();
